mapper.select:
SELECT ADMIN_NICKNAME
FROM UB_ADMIN
WHERE ADMIN_NUMBER = #{adminNumber}

mapper.update:
UPDATE UB_mentee_board
SET board_title   = #{boardTitle},
    board_content = #{boardContent}
WHERE menteeBoard_number = #{menteeboardNumber}

UPDATE UB_mentor_board
SET board_title   = #{boardTitle},
    board_content = #{boardContent}
WHERE mentorBoard_number = #{mentorboardNumber}

mapper.select:
SELECT * FROM (
    SELECT ROW_NUMBER() OVER (ORDER BY unb.NOTICEBOARD_NUMBER DESC) AS rnum,
           unb.*,
           ua.ADMIN_NICKNAME
    FROM UB_NOTICEBOARD unb
    LEFT JOIN UB_ADMIN ua ON unb.admin_number = ua.admin_number
    WHERE unb.BOARD_TYPE = #{boardType}
) paged
WHERE rnum BETWEEN #{startRow} AND #{endRow}

SELECT file_number
FROM UB_NoticeBoard
WHERE noticeboard_Number = #{boardNumber}

mapper.update:
UPDATE UB_NoticeBoard
SET board_title   = #{boardTitle},
    board_content = #{boardContent},
    file_number   = #{fileNumber}
WHERE noticeboard_number = #{noticeboardNumber}
